// Firecrawl 응답(rawHtml)에서 멜론 TOP100 행을 파싱
const html = $input.first().json.data?.rawHtml || '';
if (!html) throw new Error('Firecrawl 응답에 rawHtml이 없습니다.');

const named = { amp:'&', lt:'<', gt:'>', quot:'"', apos:"'", nbsp:' ', Eacute:'É', eacute:'é', Aacute:'Á', aacute:'á', Iacute:'Í', iacute:'í', Oacute:'Ó', oacute:'ó', Uacute:'Ú', uacute:'ú', Ntilde:'Ñ', ntilde:'ñ', Uuml:'Ü', uuml:'ü', Ouml:'Ö', ouml:'ö', Auml:'Ä', auml:'ä' };
const decode = (s) => s
  .replace(/<[^>]+>/g, '')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
  .replace(/&([a-zA-Z]+);/g, (m, n) => named[n] ?? m)
  .replace(/\s+/g, ' ').trim();

const collectedAt = $now.setZone('Asia/Seoul').toFormat('yyyy-MM-dd HH:mm');
const rows = html.split(/<tr[^>]*class="lst(?:50|100)"/).slice(1);

const results = rows.map((row) => {
  const songNo = (row.match(/data-song-no="(\d+)"/) || [])[1] || '';
  const rank = (row.match(/<span class="rank\s*">\s*(\d+)\s*<\/span>/) || [])[1];

  const titleBlock = (row.match(/<div class="ellipsis rank01">([\s\S]*?)<\/div>/) || [])[1] || '';
  const title = decode((titleBlock.match(/<a[^>]*>([\s\S]*?)<\/a>/) || [, titleBlock])[1]);

  // rank02: 가수 링크 + checkEllipsis(중복 표시) → 앞부분 a 태그만 사용
  const artistBlock = ((row.match(/<div class="ellipsis rank02">([\s\S]*?)<\/div>/) || [])[1] || '')
    .split('<span class="checkEllipsis"')[0];
  const artists = [...artistBlock.matchAll(/<a[^>]*>([\s\S]*?)<\/a>/g)].map((m) => decode(m[1]));

  // 렌더링된 HTML의 좋아요: <span class="cnt"><span class="none">총건수</span>57,627</span>
  const likeRaw = (row.match(/class="button_etc like"[\s\S]*?<span class="cnt">[\s\S]*?<\/span>([\s\S]*?)<\/span>/) || [])[1] || '';
  const likeDigits = decode(likeRaw).replace(/[^\d]/g, '');

  return {
    json: {
      songNo,
      수집일시: collectedAt,
      순위: rank ? Number(rank) : null,
      곡제목: title,
      가수: [...new Set(artists)].join(', '),
      좋아요수: likeDigits ? Number(likeDigits) : null,
    },
  };
}).filter((r) => r.json.순위 && r.json.곡제목);

if (results.length === 0) {
  throw new Error('차트 행을 찾지 못했습니다. 멜론 HTML 구조가 바뀌었거나 차단되었을 수 있습니다.');
}
return results;

// 좋아요수 보정: 멜론 좋아요 API 값으로 채우고(없으면 Firecrawl HTML 값 유지) 시트용 필드만 남김
const likeMap = {};
for (const it of $input.first().json.contsLike || []) likeMap[String(it.CONTSID)] = it.SUMMCNT;

return $('순위·곡제목·가수 추출').all().map(({ json: s }) => ({
  json: {
    수집일시: s.수집일시,
    순위: s.순위,
    곡제목: s.곡제목,
    가수: s.가수,
    좋아요수: likeMap[s.songNo] ?? s.좋아요수 ?? '',
  },
}));
